function addSelector(){
 const nav=document.querySelector('[data-nav]');if(!nav||document.querySelector('[data-sub-lang]'))return;
 const s=document.createElement('select');s.dataset.subLang='1';s.setAttribute('aria-label','Language');
 s.style.cssText='background:#101712;color:#fff;border:1px solid rgba(255,255,255,.24);border-radius:9px;padding:8px 26px 8px 9px;font:inherit;cursor:pointer';
 supported.forEach(c=>{const o=document.createElement('option');o.value=c;o.textContent=names[c];o.selected=c===lang;s.appendChild(o)});
 s.onchange=()=>{localStorage.setItem('traileye-lang',s.value);const u=new URL(location.href);u.searchParams.set('lang',s.value);location.href=u};
 nav.insertBefore(s,nav.querySelector('.nav-cta')||null);
}
function preserveLang(){
 document.querySelectorAll('a[href]').forEach(a=>{const h=a.getAttribute('href');if(!h||h.startsWith('#')||h.startsWith('mailto:')||h.startsWith('http'))return;try{const u=new URL(h,location.href);if(u.origin===location.origin){u.searchParams.set('lang',lang);a.href=u.pathname+u.search+u.hash}}catch{}});
}
function translate(map){
 const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT,{acceptNode(n){const p=n.parentElement;if(!p||['SCRIPT','STYLE','SELECT','OPTION'].includes(p.tagName))return NodeFilter.FILTER_REJECT;return n.nodeValue.trim()?NodeFilter.FILTER_ACCEPT:NodeFilter.FILTER_REJECT}});
 const nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);
 nodes.forEach(n=>{const raw=n.nodeValue,t=raw.trim();if(map[t])n.nodeValue=raw.replace(t,map[t])});
}
